CREATE TABLE users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY,name text NOT NULL,response_minutes integer NOT NULL DEFAULT 240 CHECK(response_minutes>0),resolution_minutes integer NOT NULL DEFAULT 2880 CHECK(resolution_minutes>0),guidelines text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(org_id uuid REFERENCES organizations ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','agent','customer')),PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,csrf_token text NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE invitations(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,email text NOT NULL,role text NOT NULL CHECK(role IN ('admin','agent','customer')),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,created_by uuid REFERENCES users,subject text NOT NULL,body text NOT NULL,customer_email text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','pending','resolved','closed')),priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),category text NOT NULL DEFAULT 'general_inquiry',assignee_id uuid,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),first_response_at timestamptz,resolved_at timestamptz,response_due_at timestamptz NOT NULL,resolution_due_at timestamptz NOT NULL,escalated_at timestamptz,UNIQUE(org_id,id),FOREIGN KEY(org_id,assignee_id) REFERENCES memberships(org_id,user_id));
CREATE INDEX tickets_listing ON tickets(org_id,status,created_at DESC);
CREATE INDEX tickets_assignee ON tickets(org_id,assignee_id);
CREATE INDEX tickets_sla ON tickets(resolution_due_at) WHERE status NOT IN ('resolved','closed');
CREATE TABLE messages(id uuid PRIMARY KEY,org_id uuid NOT NULL,ticket_id uuid NOT NULL,author_id uuid REFERENCES users,author_name text NOT NULL,body text NOT NULL,internal boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,ticket_id) REFERENCES tickets(org_id,id) ON DELETE CASCADE);
CREATE INDEX messages_timeline ON messages(org_id,ticket_id,created_at);
CREATE TABLE activities(id uuid PRIMARY KEY,org_id uuid NOT NULL,ticket_id uuid NOT NULL,actor_id uuid REFERENCES users,kind text NOT NULL,detail text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,ticket_id) REFERENCES tickets(org_id,id) ON DELETE CASCADE);
CREATE TABLE documents(id uuid PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,title text NOT NULL,content text NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX documents_tenant ON documents(org_id);
CREATE TABLE drafts(id uuid PRIMARY KEY,org_id uuid NOT NULL,ticket_id uuid NOT NULL,body text NOT NULL,citations jsonb NOT NULL,category text NOT NULL,priority text NOT NULL,explanation text NOT NULL,provider text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),ticket_version integer NOT NULL,latency_ms integer,usage jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,ticket_id) REFERENCES tickets(org_id,id) ON DELETE CASCADE);
CREATE TABLE audit_logs(id uuid PRIMARY KEY,org_id uuid REFERENCES organizations ON DELETE CASCADE,actor_id uuid REFERENCES users,action text NOT NULL,resource_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id uuid PRIMARY KEY,org_id uuid NOT NULL,ticket_id uuid NOT NULL,recipient text NOT NULL,subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,provider_id text,last_error text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,ticket_id) REFERENCES tickets(org_id,id) ON DELETE CASCADE);
CREATE INDEX outbox_pending ON outbox(status,available_at);
CREATE TABLE inbound_events(event_id text PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_resets(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL);
